const PROMPTS = [
  {
    name: 'summarize',
    description: 'Summarize a topic for a given audience.',
    arguments: [
      { name: 'topic', description: 'The topic to summarize.', required: true },
      { name: 'audience', description: 'The target audience.', required: false }
    ]
  }
];

const PROMPT_BY_NAME = new Map(PROMPTS.map(p => [p.name, p]));

export async function listPrompts(){return PROMPTS}

export async function getPrompt(name, args = {}){
  const prompt = PROMPT_BY_NAME.get(name);
  if (!prompt) {
    const err = new Error(`Unknown prompt: ${name}`);
    err.code = -32602;
    throw err;
  }

  args = args || {};
  const allowed = new Set(prompt.arguments.map(a => a.name));
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      const err = new Error(`Unknown argument for prompt "${name}": ${key}`);
      err.code = -32602;
      throw err;
    }
  }

  for (const arg of prompt.arguments) {
    if (arg.required && args[arg.name] === undefined) {
      const err = new Error(`Missing required argument for prompt "${name}": ${arg.name}`);
      err.code = -32602;
      throw err;
    }
  }

  const topic = args.topic;
  const audience = args.audience ?? 'general';
  const text = `Summarize the topic "${topic}" for a ${audience} audience.`;

  return {
    description: prompt.description,
    messages: [
      {
        role: 'user',
        content: { type: 'text', text }
      }
    ]
  };
}

